files.content:
body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #1a1c2c;
  font-family: 'Courier New', monospace;
  color: #fff;
}
.pixel-panel {
  background: #29366f;
  border: 4px solid #fff;
  box-shadow: 0 0 0 4px #29366f, 8px 8px 0 #000;
  padding: 24px;
  width: min(360px, 90vw);
}
h1 {
  margin-top: 0;
  font-size: 24px;
  text-shadow: 2px 2px #000;
}
label, output {
  display: block;
  margin: 12px 0 4px;
}
input, select, button {
  width: 100%;
  box-sizing: border-box;
  padding: 8px;
  font: inherit;
  background: #1a1c2c;
  color: #fff;
  border: 3px solid #fff;
}
input:focus, select:focus, button:focus, output:focus {
  outline: 3px dashed #ffd93d;
  outline-offset: 2px;
}
button {
  background: #e13b3b;
  cursor: pointer;
  margin-top: 12px;
  text-transform: uppercase;
  font-weight: bold;
}
button:hover {
  background: #ff5e5e;
}
#result {
  background: #000;
  border: 3px solid #fff;
  padding: 12px;
  font-size: 24px;
  min-height: 32px;
  text-align: right;
}
.formula {
  background: #000;
  padding: 8px;
  border: 2px solid #fff;
  font-size: 14px;
}

const tempInput = document.getElementById('temperature');
const direction = document.getElementById('direction');
const convertBtn = document.getElementById('convert');
const result = document.getElementById('result');
const formula = document.getElementById('formula');

function updateFormula() {
  formula.textContent = direction.value === 'c-to-f'
    ? 'F = C × 9/5 + 32'
    : 'C = (F - 32) × 5/9';
}

function convert() {
  const raw = tempInput.value.trim();
  if (raw === '') {
    result.textContent = 'Error';
    return;
  }
  const temp = Number(raw);
  if (!Number.isFinite(temp)) {
    result.textContent = 'Error';
    return;
  }
  const output = direction.value === 'c-to-f'
    ? temp * 9 / 5 + 32
    : (temp - 32) * 5 / 9;
  result.textContent = output.toFixed(2);
}

convertBtn.addEventListener('click', convert);
direction.addEventListener('change', updateFormula);
tempInput.addEventListener('keydown', (event) => {
  if (event.key === 'Enter') convert();
});

updateFormula();
